


export type DeliveryRateCallbackTestDelivery = { "delivery_rate_callback_id": string; "delivery_rate_callback_revision_id": string; /** Why the callback test failed and the action that can make the next test succeed. - `blocked_target`: Use a public HTTPS callback target allowed by Flint's outbound network policy. - `connection_error`: Restore network connectivity to the callback host, then test again. - `dns_error`: Fix the callback hostname or its DNS records, then test again. - `invalid_response`: Return the documented callback response status, headers, and JSON body, then test again. - `request_error`: Fix the callback request handling identified by the test result, then test again. - `timeout`: Acknowledge the callback within its configured timeout, then test again. - `tls_error`: Fix the callback certificate and TLS configuration, then test again. */ "failure_category"?: "blocked_target" | "connection_error" | "dns_error" | "invalid_response" | "request_error" | "timeout" | "tls_error" | (string & {}); "http_status_code"?: number; "key_id": string; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "latency_milliseconds": string; "status": "succeeded" | "failed" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "tested_at": string; };
